<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;
class FinancialTransaction extends Model{protected $fillable=['uuid','studio_owner_id','category','transaction_type','source_type','source_id','description','currency','subtotal_amount_minor','discount_amount_minor','tax_amount_minor','total_amount_minor','credit_units','direction','status','payment_provider','provider_reference','payment_method_summary','refund_state','refund_amount_minor','safe_details','occurred_at'];protected $casts=['subtotal_amount_minor'=>'integer','discount_amount_minor'=>'integer','tax_amount_minor'=>'integer','total_amount_minor'=>'integer','credit_units'=>'integer','refund_amount_minor'=>'integer','safe_details'=>'array','occurred_at'=>'datetime'];public function getRouteKeyName(){return'uuid';}protected static function booted(){static::deleting(fn()=>throw new \LogicException('Financial transactions are immutable.'));static::updating(function($m){if(in_array($m->getOriginal('status'),['paid','completed','refunded','reversed'],true)&&$m->isDirty(['subtotal_amount_minor','tax_amount_minor','total_amount_minor','currency','provider_reference']))throw new \LogicException('Completed financial amounts are immutable.');});}}
